INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(883144, 101293, 24494, '<td valign="top">very....  i''m not sure what to say but i love this shot</td>', 'very....  i''m not sure what to say but i love this shot', '2004-08-30 01:06:23.000000', NULL, 1),
(883148, 100694, 93, '<td valign="top">The lighting and saturation on this photo are absolutely *STUNNING*.  Her expression is very anti-classic, and a little haunting.  I could do without the flower in the background, it''s color seems to throw the shot off a little, but an excellent photograph. Very reminiscent of fairy child..<br/> <br/>I do believe in fairies.. I do.. I do!</td>', 'The lighting and saturation on this photo are absolutely *STUNNING*.  Her expression is very anti-classic, and a little haunting.  I could do without the flower in the background, it''s color seems to throw the shot off a little, but an excellent photograph. Very reminiscent of fairy child.. I do believe in fairies.. I do.. I do!', '2004-08-30 01:07:39.000000', NULL, 1),
(883149, 101340, 17837, '<td valign="top">Wasnt the goose that laid the golden egg from Willy Wonka? I don''t think this is a fairy tale...<br/> <br/>As far as the photo is concerned, I believe that you could have burned the water to match the right side, right now its being blown out. other than that, ok colors, good focus.</td>', 'Wasnt the goose that laid the golden egg from Willy Wonka? I don''t think this is a fairy tale... As far as the photo is concerned, I believe that you could have burned the water to match the right side, right now its being blown out. other than that, ok colors, good focus.', '2004-08-30 01:08:15.000000', NULL, 1),
(883150, 100873, 24494, '<td valign="top">great idea i love it!!!</td>', 'great idea i love it!!!', '2004-08-30 01:08:25.000000', NULL, 1),
(883162, 101340, 12694, '<td valign="top">i''m a goose from canade....eh.</td>', 'i''m a goose from canade....eh.', '2004-08-30 01:11:18.000000', NULL, 1),
(883164, 101349, 93, '<td valign="top">I find the white area a little blown out and there''s just too much of it in my opinion, and the beans are out of focus (perhaps a result of shooting through a magnifying glass?)  Also, I think that it needs another element of some sort to relate it more to Jack.</td>', 'I find the white area a little blown out and there''s just too much of it in my opinion, and the beans are out of focus (perhaps a result of shooting through a magnifying glass?)  Also, I think that it needs another element of some sort to relate it more to Jack.', '2004-08-30 01:11:30.000000', NULL, 1),
(883165, 100872, 21034, '<td valign="top">This is great. Very well composed -- should''ve had him light up. :)</td>', 'This is great. Very well composed -- should''ve had him light up. :)', '2004-08-30 01:11:31.000000', NULL, 1),
(883168, 101021, 12694, '<td valign="top">no princess is gonna wanna kiss that from while hes humping that stick!!!  (good photo tho, love the crown!)</td>', 'no princess is gonna wanna kiss that from while hes humping that stick!!!  (good photo tho, love the crown!)', '2004-08-30 01:13:08.000000', NULL, 1),
(883169, 101030, 93, '<td valign="top">A nice photograph. Sharply focused on his eyes, which is where we''re supposed to look, and the lighting/colors are beautiful. I''m not too keen on the background behind the dragon though. It sort of rips me out of the fantasy, but it''s a minor complaint.</td>', 'A nice photograph. Sharply focused on his eyes, which is where we''re supposed to look, and the lighting/colors are beautiful. I''m not too keen on the background behind the dragon though. It sort of rips me out of the fantasy, but it''s a minor complaint.', '2004-08-30 01:13:21.000000', NULL, 1),
(883174, 100989, 93, '<td valign="top">I like the costuming on this portrait, and the wistful look in the model''s face.  The depth of field isn''t as forgiving as it could be.. the right shoulder strap is an example.  I like it, however, overall.</td>', 'I like the costuming on this portrait, and the wistful look in the model''s face.  The depth of field isn''t as forgiving as it could be.. the right shoulder strap is an example.  I like it, however, overall.', '2004-08-30 01:15:50.000000', NULL, 1),
(883178, 100808, 93, '<td valign="top">creative..  I''d like to find out how you achieved the rainbow effect.. or what you shot this through.</td>', 'creative..  I''d like to find out how you achieved the rainbow effect.. or what you shot this through.', '2004-08-30 01:16:32.000000', NULL, 1),
(883179, 100859, 24494, '<td valign="top">where are his back legs you mean grasshopper chopper upper</td>', 'where are his back legs you mean grasshopper chopper upper', '2004-08-30 01:16:40.000000', NULL, 1),
(883181, 100884, 6349, '<td valign="top">Funny take on the challenge.  He sort of reminds me of Keiffer Sutherland.</td>', 'Funny take on the challenge.  He sort of reminds me of Keiffer Sutherland.', '2004-08-30 01:17:01.000000', NULL, 1),
(883184, 100873, 6349, '<td valign="top">An empty turtle shell!  What an awesome subject.</td>', 'An empty turtle shell!  What an awesome subject.', '2004-08-30 01:17:55.000000', NULL, 1),
(883185, 101267, 24494, '<td valign="top">wow this is great good job</td>', 'wow this is great good job', '2004-08-30 01:18:07.000000', NULL, 1),
(883186, 100856, 93, '<td valign="top">Boy, Robin Hood sure has gotten modern! :)  I like the POV, and the look of concentration.  Would have been nice if you could have found more "earthy" tones for the boy to wear, as it would have sold the "Robin Hood" theme a touch better.<br/>However, it''s still a pretty good photograph.</td>', 'Boy, Robin Hood sure has gotten modern! :)  I like the POV, and the look of concentration.  Would have been nice if you could have found more "earthy" tones for the boy to wear, as it would have sold the "Robin Hood" theme a touch better.However, it''s still a pretty good photograph.', '2004-08-30 01:18:25.000000', NULL, 1),
(883187, 101293, 16301, '<td valign="top">Simply stunning, I like the painterly feel, it fits the theme very well. I could actually hear everyhing going on in this photo. (10)<br/> <br/>Good luck...</td>', 'Simply stunning, I like the painterly feel, it fits the theme very well. I could actually hear everyhing going on in this photo. (10) Good luck...', '2004-08-30 01:18:38.000000', NULL, 1),
(883188, 100591, 6349, '<td valign="top">hahaha.  you''ve got a cool kid there.  People who are really that scared of bugs creep me out more than bugs themselves.</td>', 'hahaha.  you''ve got a cool kid there.  People who are really that scared of bugs creep me out more than bugs themselves.', '2004-08-30 01:19:22.000000', NULL, 1),
(883190, 100715, 24494, '<td valign="top">puss in shoes close friend of puss in boots i like it 8</td>', 'puss in shoes close friend of puss in boots i like it 8', '2004-08-30 01:20:11.000000', NULL, 1),
(883192, 101269, 93, '<td valign="top">lol.. I can''t believe it.. it actually took me a few blinks and some "huh?"s to get the play on words :)<br/>I like the humor, but the stalk kind of disappears into the clutter of the fence a little too much. perhaps a different POV would have made a difference. The jack''s highlights could have been toned down a little too, in my opinion, as well.  Good try!</td>', 'lol.. I can''t believe it.. it actually took me a few blinks and some "huh?"s to get the play on words :)I like the humor, but the stalk kind of disappears into the clutter of the fence a little too much. perhaps a different POV would have made a difference. The jack''s highlights could have been toned down a little too, in my opinion, as well.  Good try!', '2004-08-30 01:20:55.000000', NULL, 1),
(883194, 101351, 6349, '<td valign="top">labuda?  Great concept and execution on this one.  Might have been slightly more appealing with a newer white piggy bank.</td>', 'labuda?  Great concept and execution on this one.  Might have been slightly more appealing with a newer white piggy bank.', '2004-08-30 01:21:01.000000', NULL, 1),
(883195, 101033, 6349, '<td valign="top">looks like the french little red riding hood to me.  The lighting is very magical.  Oui oui.</td>', 'looks like the french little red riding hood to me.  The lighting is very magical.  Oui oui.', '2004-08-30 01:21:41.000000', NULL, 1),
(883199, 101403, 6349, '<td valign="top">I really like this modern take on an old classic!</td>', 'I really like this modern take on an old classic!', '2004-08-30 01:23:07.000000', NULL, 1),
(883201, 101048, 12694, '<td valign="top">tastes like chicken?</td>', 'tastes like chicken?', '2004-08-30 01:23:12.000000', NULL, 1),
(883202, 101384, 93, '<td valign="top">This is a very beautiful photo to look at. You''ve saturated the red almost to perfection in my eyes.. (or as close to as one can come),  and the dog was a very nice touch.  The one flaw I see is that the saturation has made the girl stand out a little *too* much.. as if she was pasted in to the picture.  perhaps some softening of the edges or blending would have helped that.</td>', 'This is a very beautiful photo to look at. You''ve saturated the red almost to perfection in my eyes.. (or as close to as one can come),  and the dog was a very nice touch.  The one flaw I see is that the saturation has made the girl stand out a little *too* much.. as if she was pasted in to the picture.  perhaps some softening of the edges or blending would have helped that.', '2004-08-30 01:23:21.000000', NULL, 1),
(883204, 100694, 24494, '<td valign="top">shes a cutie 8</td>', 'shes a cutie 8', '2004-08-30 01:24:16.000000', NULL, 1),
(883206, 100813, 6349, '<td valign="top">Get rid of the freakish prince with the freshly and rather poorly died blue hair (no offense if it''s you, I actually died my hair blue black for this challenge too but then ended up going black and white anyway :) and you have yourself a winning photo here.</td>', 'Get rid of the freakish prince with the freshly and rather poorly died blue hair (no offense if it''s you, I actually died my hair blue black for this challenge too but then ended up going black and white anyway :) and you have yourself a winning photo here.', '2004-08-30 01:25:07.000000', NULL, 1),
(883207, 101289, 93, '<td valign="top">absolutely gorgeous!  One of these days I''ll be able to accumulate enough props to do something like this :)  Anyway, props aside, you''ve done a wonderful job with capturing the moment, and handling the light.  This piece really puts me in the moment.</td>', 'absolutely gorgeous!  One of these days I''ll be able to accumulate enough props to do something like this :)  Anyway, props aside, you''ve done a wonderful job with capturing the moment, and handling the light.  This piece really puts me in the moment.', '2004-08-30 01:25:20.000000', NULL, 1),
(883211, 101042, 6349, '<td valign="top">Your title is cracking me up.  I must still be a kid at heart because it is scaring me.</td>', 'Your title is cracking me up.  I must still be a kid at heart because it is scaring me.', '2004-08-30 01:25:57.000000', NULL, 1),
(883213, 101410, 15207, '<td valign="top">ONe of the best I''ve seen in any challenge ever. IF you don''t get first place I''ll be totally surprised. Amazing job. I love that it''s original, fits the challenge, plus it''s pitch perfect photography. Lighting, composition, everything is perfect.</td>', 'ONe of the best I''ve seen in any challenge ever. IF you don''t get first place I''ll be totally surprised. Amazing job. I love that it''s original, fits the challenge, plus it''s pitch perfect photography. Lighting, composition, everything is perfect.', '2004-08-30 01:26:02.000000', NULL, 1),
(883217, 101048, 93, '<td valign="top">a very humorous photo :)  Her face seems to be a little blurred, and the frog might have been helped by being lightened up a little. Just a thought.  Overall, this is well executed.</td>', 'a very humorous photo :)  Her face seems to be a little blurred, and the frog might have been helped by being lightened up a little. Just a thought.  Overall, this is well executed.', '2004-08-30 01:27:08.000000', NULL, 1),
(883218, 101169, 6349, '<td valign="top">hahahaha.  where did you find this rare treasure?!</td>', 'hahahaha.  where did you find this rare treasure?!', '2004-08-30 01:27:34.000000', NULL, 1),
(883223, 100428, 6349, '<td valign="top">holy crap!  what is that?  It does look like a troll!</td>', 'holy crap!  what is that?  It does look like a troll!', '2004-08-30 01:27:54.000000', NULL, 1),
(883227, 101031, 93, '<td valign="top">I think this is a nice shot, but I find the negative space too distracting, and the contrast on the model herself a little light. I find it a little too grainy also, but that''s just personal opinion, and you could have been going for that purposely, and it''s not a score affecting gripe :)</td>', 'I think this is a nice shot, but I find the negative space too distracting, and the contrast on the model herself a little light. I find it a little too grainy also, but that''s just personal opinion, and you could have been going for that purposely, and it''s not a score affecting gripe :)', '2004-08-30 01:30:03.000000', NULL, 1),
(883228, 101384, 16301, '<td valign="top">Excellent, I like the desaturation. Definitely a 10.<br/> <br/>Good luck...</td>', 'Excellent, I like the desaturation. Definitely a 10. Good luck...', '2004-08-30 01:30:31.000000', NULL, 1),
(883229, 101274, 6349, '<td valign="top">hahaha.  poor kids!  How many times did you have to scare them to get this photo?  :)</td>', 'hahaha.  poor kids!  How many times did you have to scare them to get this photo?  :)', '2004-08-30 01:30:32.000000', NULL, 1),
(883232, 101298, 93, '<td valign="top">This is an extremely creative and imaginative take on the challenge.  It''s also beautifully shot. The contrasts are nice, the focus is soft in the sheet, and sharp on the pea.  The shadow the pea makes is a *touch* strong, but minor.  Great work.</td>', 'This is an extremely creative and imaginative take on the challenge.  It''s also beautifully shot. The contrasts are nice, the focus is soft in the sheet, and sharp on the pea.  The shadow the pea makes is a *touch* strong, but minor.  Great work.', '2004-08-30 01:31:48.000000', NULL, 1),
(883233, 100989, 6349, '<td valign="top">and Here I Am!  Beautiful...</td>', 'and Here I Am!  Beautiful...', '2004-08-30 01:32:20.000000', NULL, 1),
(883237, 101325, 16301, '<td valign="top">Very cool idea, I like the colors and burning. Definitely a 10...</td>', 'Very cool idea, I like the colors and burning. Definitely a 10...', '2004-08-30 01:34:24.000000', NULL, 1),
(883238, 101359, 6349, '<td valign="top">Is that a horny toad?  He sure does look cuddley.</td>', 'Is that a horny toad?  He sure does look cuddley.', '2004-08-30 01:34:26.000000', NULL, 1),
(883240, 100694, 10080, '<td valign="top">beautiful!@!!!! I dont understand the fairy tale meaning! But the best I have seen outta the bunch!</td>', 'beautiful!@!!!! I dont understand the fairy tale meaning! But the best I have seen outta the bunch!', '2004-08-30 01:34:31.000000', NULL, 1),
(883241, 101288, 93, '<td valign="top">Oh, wonderful! Makes me want to start cliimbing it right away! Very clever, gorgeous POV, and almost the perfect type of plant.  Excellent.</td>', 'Oh, wonderful! Makes me want to start cliimbing it right away! Very clever, gorgeous POV, and almost the perfect type of plant.  Excellent.', '2004-08-30 01:34:34.000000', NULL, 1),
(883243, 101411, 6349, '<td valign="top">I love this photograph. All elements fall together perfectly, the composition, the costume, the props, the pose and expression and I very much admire the fact that it hasn''t all been done with photoshop.  I can imaging this as a screenshot from a made for tv children''s show (that''s a completely, really it is :) 10</td>', 'I love this photograph. All elements fall together perfectly, the composition, the costume, the props, the pose and expression and I very much admire the fact that it hasn''t all been done with photoshop.  I can imaging this as a screenshot from a made for tv children''s show (that''s a completely, really it is :) 10', '2004-08-30 01:36:32.000000', NULL, 1),
(883244, 100882, 93, '<td valign="top">How lucky are you for finding or having something like this around to shoot during "Fairy Tale" week?  Great shot, but I have a suggestion.  How about a closer cropping on the knight? This would help eliminate more of the distracting flag in the background, and help the viewer focus better on the subject.  Your focus from a distance is very nice as well.</td>', 'How lucky are you for finding or having something like this around to shoot during "Fairy Tale" week?  Great shot, but I have a suggestion.  How about a closer cropping on the knight? This would help eliminate more of the distracting flag in the background, and help the viewer focus better on the subject.  Your focus from a distance is very nice as well.', '2004-08-30 01:37:15.000000', NULL, 1),
(883245, 100207, 10080, '<td valign="top">great shot and the best I have seen out of this challenge! Good job!<br/></td>', 'great shot and the best I have seen out of this challenge! Good job!', '2004-08-30 01:37:19.000000', NULL, 1),
(883248, 101325, 6349, '<td valign="top">This photograph is one of my favorites in the challenge.  So beautiful in fact that you didn''t need to go overboard with the photoshop vignetting.  Great model, lighting, and pose.  10</td>', 'This photograph is one of my favorites in the challenge.  So beautiful in fact that you didn''t need to go overboard with the photoshop vignetting.  Great model, lighting, and pose.  10', '2004-08-30 01:37:35.000000', NULL, 1),
(883251, 101411, 93, '<td valign="top">Wonderful!  Adding the mist was a stroke of genius, and I *love* his expression.</td>', 'Wonderful!  Adding the mist was a stroke of genius, and I *love* his expression.', '2004-08-30 01:37:50.000000', NULL, 1),
(883252, 101287, 6349, '<td valign="top">One of my top picks for the challenge.  The lighting, model, costume, everything, just perfect.  10</td>', 'One of my top picks for the challenge.  The lighting, model, costume, everything, just perfect.  10', '2004-08-30 01:38:37.000000', NULL, 1),
(883255, 101308, 93, '<td valign="top">I understand where you''re going with this, but having a model that was actually *letting* down some hair would have done wonders for this photo.  Now, I *know* that it''d probably be impossible to get someone up there, but I really feel that it doesn''t tell the story you want it to without that element.</td>', 'I understand where you''re going with this, but having a model that was actually *letting* down some hair would have done wonders for this photo.  Now, I *know* that it''d probably be impossible to get someone up there, but I really feel that it doesn''t tell the story you want it to without that element.', '2004-08-30 01:39:19.000000', NULL, 1),
(883260, 101347, 93, '<td valign="top">I like your idea, however, the grass looks a little "fake" to me, because of the blur, and the lighting (too bright) doesn''t convey the mood very well, but the concept is great and very imaginative.</td>', 'I like your idea, however, the grass looks a little "fake" to me, because of the blur, and the lighting (too bright) doesn''t convey the mood very well, but the concept is great and very imaginative.', '2004-08-30 01:41:52.000000', NULL, 1),
(883261, 101384, 6349, '<td valign="top">I don''t remember little red riding hood having a dog; or is that supposed to be the wolf?  The dog seems only to be concerned with whatever treat is in the basket!  :)  Sorry, that''s just what came to mind when I saw the photo.  This image is excellent.  One of the best in the challenge.  I think the selected desaturation works very well here.  The only flaws in the image I see are the slightly overblow highlights on the dog and some perhaps rushed photoshopping in some spots.  Still a 10 from me though and I absolutely love it.  I''m trying to work on more constructive helpful comments.</td>', 'I don''t remember little red riding hood having a dog; or is that supposed to be the wolf?  The dog seems only to be concerned with whatever treat is in the basket!  :)  Sorry, that''s just what came to mind when I saw the photo.  This image is excellent.  One of the best in the challenge.  I think the selected desaturation works very well here.  The only flaws in the image I see are the slightly overblow highlights on the dog and some perhaps rushed photoshopping in some spots.  Still a 10 from me though and I absolutely love it.  I''m trying to work on more constructive helpful comments.', '2004-08-30 01:41:55.000000', NULL, 1),
(883265, 101410, 6349, '<td valign="top">If this crown wasn''t illegally photoshopped in I believe you have a ribbon winning prince of a photograph in your hands here.  I can''t image how you possible got it to wear it!?  :)  10</td>', 'If this crown wasn''t illegally photoshopped in I believe you have a ribbon winning prince of a photograph in your hands here.  I can''t image how you possible got it to wear it!?  :)  10', '2004-08-30 01:42:56.000000', NULL, 1),
(883266, 100503, 93, '<td valign="top">I found this photo to be a little *too* dark, and it was difficult to figure out what it was at first.  I see it now though, and I like the idea.  Try playing around with different lighting combinations perhaps, and see what you can come up with.</td>', 'I found this photo to be a little *too* dark, and it was difficult to figure out what it was at first.  I see it now though, and I like the idea.  Try playing around with different lighting combinations perhaps, and see what you can come up with.', '2004-08-30 01:43:11.000000', NULL, 1),
(883268, 101289, 6349, '<td valign="top">Lovely image.  Great lighting.  One of the best in the challenge.  I think it would be great if you played with it in black and white with the channel mixer and then brought the color layer back on top with about 30% transparency.  9</td>', 'Lovely image.  Great lighting.  One of the best in the challenge.  I think it would be great if you played with it in black and white with the channel mixer and then brought the color layer back on top with about 30% transparency.  9', '2004-08-30 01:44:17.000000', NULL, 1),
(883270, 101293, 93, '<td valign="top">This is very nice, but it''s pushing the limit for "digital art" in my eyes.  Absolutely wonderful to look at though, and very creative.</td>', 'This is very nice, but it''s pushing the limit for "digital art" in my eyes.  Absolutely wonderful to look at though, and very creative.', '2004-08-30 01:44:30.000000', NULL, 1),
(883274, 100999, 93, '<td valign="top">Great use of saturation here. I would have cropped it a little closer to the top of her head than you did, to get more of a center.  Also, I kind of find her expression reminds me of a yawn.. which could mean either she''s just going to sleep now, or she''s still tired from not getting *any* sleep because of the pea.  I can''t decide which :)</td>', 'Great use of saturation here. I would have cropped it a little closer to the top of her head than you did, to get more of a center.  Also, I kind of find her expression reminds me of a yawn.. which could mean either she''s just going to sleep now, or she''s still tired from not getting *any* sleep because of the pea.  I can''t decide which :)', '2004-08-30 01:46:47.000000', NULL, 1),
(883276, 100207, 6349, '<td valign="top">It''s great to see people going all out for the challenges.  The make-up job with the jewels is excellent as is the mood and composition.  The red lines in the eyes are a bit distracting and would be easy to remove.  A small amount of the photoshopping seems to have been rushed (ie the pinkish glow around the top of the leaf).  The hair is completely brilliant and I will have to give you a 10 for that effect alone.  10!</td>', 'It''s great to see people going all out for the challenges.  The make-up job with the jewels is excellent as is the mood and composition.  The red lines in the eyes are a bit distracting and would be easy to remove.  A small amount of the photoshopping seems to have been rushed (ie the pinkish glow around the top of the leaf).  The hair is completely brilliant and I will have to give you a 10 for that effect alone.  10!', '2004-08-30 01:46:50.000000', NULL, 1),
(883277, 101313, 93, '<td valign="top">Gorgeous.  Where''d you get that sword?! ;)</td>', 'Gorgeous.  Where''d you get that sword?! ;)', '2004-08-30 01:47:21.000000', NULL, 1),
(883280, 101396, 93, '<td valign="top">Nice play on words.  Makes you think of the *real* reason the Giant fell off the beanstalk ;)  The shadow in the top corner bothers me a little, and I don''t know what the yellow is at the bottom.  The golden egg?</td>', 'Nice play on words.  Makes you think of the *real* reason the Giant fell off the beanstalk ;)  The shadow in the top corner bothers me a little, and I don''t know what the yellow is at the bottom.  The golden egg?', '2004-08-30 01:49:05.000000', NULL, 1),
(883282, 100706, 93, '<td valign="top">Hahahahahaahah..This is fantastic!  This is thinking outside-the-box in the best of ways.  Great job.</td>', 'Hahahahahaahah..This is fantastic!  This is thinking outside-the-box in the best of ways.  Great job.', '2004-08-30 01:50:07.000000', NULL, 1),
(883287, 100870, 93, '<td valign="top">A great idea, I just find the lighting to be a little too harsh.  It''s hard to distinguish the gold from the straw.   Perhaps a little tighter shot, and a sharper focus would have helped here.</td>', 'A great idea, I just find the lighting to be a little too harsh.  It''s hard to distinguish the gold from the straw.   Perhaps a little tighter shot, and a sharper focus would have helped here.', '2004-08-30 01:51:20.000000', NULL, 1),
(883291, 100858, 93, '<td valign="top">Great idea.  The lighting really gives the troll a realistic feel, and the POV helps me feel that I''m a traveller accidentally discovering this scene. Nice job.</td>', 'Great idea.  The lighting really gives the troll a realistic feel, and the POV helps me feel that I''m a traveller accidentally discovering this scene. Nice job.', '2004-08-30 01:52:20.000000', NULL, 1),
(883293, 101405, 93, '<td valign="top">This is a great idea.  I imagine the ripple effect was photoshopped? I don''t know enough about the rules to know if this''ll put your photo in danger of DQ, but regardless, I really like the idea and execution of this. The lighting is very nice.</td>', 'This is a great idea.  I imagine the ripple effect was photoshopped? I don''t know enough about the rules to know if this''ll put your photo in danger of DQ, but regardless, I really like the idea and execution of this. The lighting is very nice.', '2004-08-30 01:53:45.000000', NULL, 1),
(883296, 100207, 93, '<td valign="top">I just want to congratulate your model for being such a sport as to let you paint her.. unless, of course, this is all just hues :)  A great look in her face.. very mischevous.</td>', 'I just want to congratulate your model for being such a sport as to let you paint her.. unless, of course, this is all just hues :)  A great look in her face.. very mischevous.', '2004-08-30 01:55:09.000000', NULL, 1),
(883297, 100691, 93, '<td valign="top">absolutely wonderful shot.  I can''t wait to find out what you used for the sparking effect.. just a regluar sparkler, and then played with levels?</td>', 'absolutely wonderful shot.  I can''t wait to find out what you used for the sparking effect.. just a regluar sparkler, and then played with levels?', '2004-08-30 01:56:45.000000', NULL, 1),
