(883967, 100873, 24951, '<td valign="top">Are you referring to the fable the tortoise &amp; the hare?</td>', 'Are you referring to the fable the tortoise & the hare?', '2004-08-30 13:07:26.000000', NULL, 1),
(883968, 101393, 10848, '<td valign="top">This is beautiful, wonderful lighting</td>', 'This is beautiful, wonderful lighting', '2004-08-30 13:07:36.000000', NULL, 1),
(883972, 100549, 19425, '<td valign="top">i like the shot, but if i gonna be picky, i''d say that you shoud have cloned out the "frays" in the red dress. Or maybe you meant them to be there.....</td>', 'i like the shot, but if i gonna be picky, i''d say that you shoud have cloned out the "frays" in the red dress. Or maybe you meant them to be there.....', '2004-08-30 13:09:40.000000', NULL, 1),
