(884591, 101272, 23312, '<td valign="top">I think cropping in would give the picture more punch.</td>', 'I think cropping in would give the picture more punch.', '2004-08-30 21:19:30.000000', NULL, 1),
(884593, 101403, 164, '<td valign="top">Great idea and execution - lighting on red could be better.</td>', 'Great idea and execution - lighting on red could be better.', '2004-08-30 21:20:03.000000', NULL, 1),
