(884601, 101412, 23956, '<td valign="top">isn''t this backwards? nice shot, good tones and composition.</td>', 'isn''t this backwards? nice shot, good tones and composition.', '2004-08-30 21:29:58.000000', NULL, 1),
(884604, 101314, 23956, '<td valign="top">Very nicely done!</td>', 'Very nicely done!', '2004-08-30 21:31:11.000000', NULL, 1),
(884608, 100873, 23956, '<td valign="top">A solid red ribbon would work better here than a bumpy purple one. It took me a second to figure out that it was supposed to be the finish line. Otherwise very good, nice control of depth. The Highlights are a bit too blown, using a bit of white cloth to shade the background would have helped.</td>', 'A solid red ribbon would work better here than a bumpy purple one. It took me a second to figure out that it was supposed to be the finish line. Otherwise very good, nice control of depth. The Highlights are a bit too blown, using a bit of white cloth to shade the background would have helped.', '2004-08-30 21:35:56.000000', NULL, 1),
(884613, 101384, 23956, '<td valign="top">Very nice traditional rendition. I think this might be a bit better if the ''wolf'' wasn''t so close. Great use of desaturation, good expressions on both the model and the dog. Well done!</td>', 'Very nice traditional rendition. I think this might be a bit better if the ''wolf'' wasn''t so close. Great use of desaturation, good expressions on both the model and the dog. Well done!', '2004-08-30 21:38:45.000000', NULL, 1),
(884620, 100870, 23956, '<td valign="top">This image would be much improved if you ironed the backdrop, and make it curve at a more gentle angle.</td>', 'This image would be much improved if you ironed the backdrop, and make it curve at a more gentle angle.', '2004-08-30 21:44:56.000000', NULL, 1),
(884621, 101400, 23956, '<td valign="top">Having the large concentration of sparkles at the bottom of the image would work if we could see a specific direction they took from the wand, but these really look like they''re coming from below the wand. Could you have hidden the sparkler behind the wand to get a more realistic spark direction?</td>', 'Having the large concentration of sparkles at the bottom of the image would work if we could see a specific direction they took from the wand, but these really look like they''re coming from below the wand. Could you have hidden the sparkler behind the wand to get a more realistic spark direction?', '2004-08-30 21:47:21.000000', NULL, 1),
(884622, 100993, 23956, '<td valign="top">Nice composition, very clean.</td>', 'Nice composition, very clean.', '2004-08-30 21:48:03.000000', NULL, 1),
(884624, 101002, 23956, '<td valign="top">Two extra points for the title and the sentiment! I think he would fit better in tall tales or hoaxes, though. Let''s hope for a fairytale ending in the near future!</td>', 'Two extra points for the title and the sentiment! I think he would fit better in tall tales or hoaxes, though. Let''s hope for a fairytale ending in the near future!', '2004-08-30 21:52:58.000000', NULL, 1),
(884625, 101287, 23956, '<td valign="top">Absolutely stunning. Is this meant to be Alana, or some other?</td>', 'Absolutely stunning. Is this meant to be Alana, or some other?', '2004-08-30 21:55:21.000000', NULL, 1),
(884627, 101351, 23956, '<td valign="top">Your hand looks a bit fuzzy. I''m guessing it was from a shutter speed a bit to slow to stop some slight motion, since it looks like it was the only thing not held in place. Nicely done, though, and a good choice of background color. I love shots done like this.</td>', 'Your hand looks a bit fuzzy. I''m guessing it was from a shutter speed a bit to slow to stop some slight motion, since it looks like it was the only thing not held in place. Nicely done, though, and a good choice of background color. I love shots done like this.', '2004-08-30 21:58:05.000000', NULL, 1),
(884631, 101267, 9264, '<td valign="top">haha VERY nice, I like!!</td>', 'haha VERY nice, I like!!', '2004-08-30 22:01:07.000000', NULL, 1),
(884639, 101396, 22320, '<td valign="top">HAHAHA! i like this. it made me laugh out loud. thank you.</td>', 'HAHAHA! i like this. it made me laugh out loud. thank you.', '2004-08-30 22:17:33.000000', NULL, 1),
(884653, 101030, 24967, '<td valign="top">Well composed, great color.</td>', 'Well composed, great color.', '2004-08-30 22:33:48.000000', NULL, 1),
(884657, 100542, 24967, '<td valign="top">Beautiful shot, but loosely related to challenge.  This was a tough one though.</td>', 'Beautiful shot, but loosely related to challenge.  This was a tough one though.', '2004-08-30 22:35:08.000000', NULL, 1),
(884658, 101298, 24967, '<td valign="top">Simple, yet well composed.  I knew exactly where you were going right away.  Well done.</td>', 'Simple, yet well composed.  I knew exactly where you were going right away.  Well done.', '2004-08-30 22:36:46.000000', NULL, 1),
(884660, 101325, 17547, '<td valign="top">outstanding, great work my pick for the blue ribbon.</td>', 'outstanding, great work my pick for the blue ribbon.', '2004-08-30 22:39:11.000000', NULL, 1),
