(884765, 100694, 17851, '<td valign="top">exelent portrait</td>', 'exelent portrait', '2004-08-30 23:32:22.000000', NULL, 1),
(884771, 101289, 19982, '<td valign="top">I guess I don''t know this fairy tale, but it''s a beautiful image!    Good luck in the challenge.</td>', 'I guess I don''t know this fairy tale, but it''s a beautiful image!    Good luck in the challenge.', '2004-08-30 23:36:05.000000', NULL, 1),
(884775, 101405, 21034, '<td valign="top">I gave this one my only 10 for this challenge. The idea was simple enough, but wonderfully executed.  In hindsight, I wonder if adding more color to the reflection in the mirror would give this one a little more pizzaz, but as is, I still think it shoujld get a ribbon. Good luck.</td>', 'I gave this one my only 10 for this challenge. The idea was simple enough, but wonderfully executed.  In hindsight, I wonder if adding more color to the reflection in the mirror would give this one a little more pizzaz, but as is, I still think it shoujld get a ribbon. Good luck.', '2004-08-30 23:40:54.000000', NULL, 1),
(884778, 100869, 21034, '<td valign="top">You might''ve smoothed out some of the wrinkles in her dress, but I really like the way the lighting affected the mood here. The brightness of the top right balances well with the foliage on the bottom left.</td>', 'You might''ve smoothed out some of the wrinkles in her dress, but I really like the way the lighting affected the mood here. The brightness of the top right balances well with the foliage on the bottom left.', '2004-08-30 23:42:27.000000', NULL, 1),
(884780, 101169, 21034, '<td valign="top">That''s an interesting angle. :)</td>', 'That''s an interesting angle. :)', '2004-08-30 23:43:17.000000', NULL, 1),
(884781, 100989, 21034, '<td valign="top">Greating lighting and I like your choice for depth of field.</td>', 'Greating lighting and I like your choice for depth of field.', '2004-08-30 23:43:56.000000', NULL, 1),
(884782, 101027, 21034, '<td valign="top">Is that a happy face in the clouds on the top right?</td>', 'Is that a happy face in the clouds on the top right?', '2004-08-30 23:44:38.000000', NULL, 1),
(884784, 101325, 17851, '<td valign="top">very magical, awesome job</td>', 'very magical, awesome job', '2004-08-30 23:45:23.000000', NULL, 1),
(884785, 100884, 21034, '<td valign="top">Awesome lighting and great bacground. Looks like a nice guy. ; )</td>', 'Awesome lighting and great bacground. Looks like a nice guy. ; )', '2004-08-30 23:45:25.000000', NULL, 1),
(884792, 100813, 21034, '<td valign="top">Love the idea, but the composition seems off somehow. His black shirt seems to leave too much dead space on the left side of the image, and the tips of the windows at the top are distracting.  The lighting is great, though.</td>', 'Love the idea, but the composition seems off somehow. His black shirt seems to leave too much dead space on the left side of the image, and the tips of the windows at the top are distracting.  The lighting is great, though.', '2004-08-30 23:48:39.000000', NULL, 1),
(884795, 100694, 21034, '<td valign="top">You actually got a girl this age to pose for you. Kudos to the cooperative model and excellent composition. You might''ve cropped a little more off of the left side, but I really like it as is.</td>', 'You actually got a girl this age to pose for you. Kudos to the cooperative model and excellent composition. You might''ve cropped a little more off of the left side, but I really like it as is.', '2004-08-30 23:50:05.000000', NULL, 1),
(884798, 101293, 21034, '<td valign="top">The overall mood is great, but I can''t quite tell what is going on here. The shadowy figure is running away, right?</td>', 'The overall mood is great, but I can''t quite tell what is going on here. The shadowy figure is running away, right?', '2004-08-30 23:51:15.000000', NULL, 1),
(884807, 101287, 19982, '<td valign="top">Beautiful image, love the lighting.    Good luck in the challenge.</td>', 'Beautiful image, love the lighting.    Good luck in the challenge.', '2004-08-30 23:55:12.000000', NULL, 1),
(884825, 99817, 19982, '<td valign="top">It''s almost always best to have the camera look your subject right in the eye.  So a better angle (down low) would have given the frog a better appearance.  It would also have solved the harsh light coming from the reflected sky.</td>', 'It''s almost always best to have the camera look your subject right in the eye.  So a better angle (down low) would have given the frog a better appearance.  It would also have solved the harsh light coming from the reflected sky.', '2004-08-31 00:04:02.000000', NULL, 1);
