(884856, 101267, 20613, '<td valign="top">haha this is hilarious!  I love it.  I like how you blurred the shot.  great job!</td>', 'haha this is hilarious!  I love it.  I like how you blurred the shot.  great job!', '2004-08-31 00:23:22.000000', NULL, 1),
(884860, 100691, 19982, '<td valign="top">Interesting effect.  Love the angles and placement within the photo.    Good luck in the challenge.</td>', 'Interesting effect.  Love the angles and placement within the photo.    Good luck in the challenge.', '2004-08-31 00:29:46.000000', NULL, 1),
