(890307, 100691, 8860, '<td valign="top">Your sparks look fantastic! I''m not a fan of tacky magic wands but, as gay accessories go, this is as good as it gets.  : )<br/> <br/>A great capture. well arranged and perfectly in tune with the challenge - if a little obvious.</td>', 'Your sparks look fantastic! I''m not a fan of tacky magic wands but, as gay accessories go, this is as good as it gets.  : ) A great capture. well arranged and perfectly in tune with the challenge - if a little obvious.', '2004-09-02 21:23:00.000000', NULL, 1),
(890358, 101411, 10818, '<td valign="top">Perfect take on the contest, great expression, fantastic shot !</td>', 'Perfect take on the contest, great expression, fantastic shot !', '2004-09-02 22:08:37.000000', NULL, 1),
(890361, 100989, 10818, '<td valign="top">What a beautiful young lady, gorgeous portrait.</td>', 'What a beautiful young lady, gorgeous portrait.', '2004-09-02 22:10:16.000000', NULL, 1),
(890369, 100858, 10818, '<td valign="top">Great environment for a troll, really cool shot.  The light and reflection really make the photo.</td>', 'Great environment for a troll, really cool shot.  The light and reflection really make the photo.', '2004-09-02 22:14:42.000000', NULL, 1),
