(890402, 101289, 10818, '<td valign="top">Wonderful photo that looks like it could be a movie poster.   The lantern and the lights from it are great !</td>', 'Wonderful photo that looks like it could be a movie poster.   The lantern and the lights from it are great !', '2004-09-02 22:54:22.000000', NULL, 1),
(890453, 101298, 1031, '<td valign="top">I''m glad someone used this idea ... if I had it wouldn''t have looked this good : )</td>', 'I''m glad someone used this idea ... if I had it wouldn''t have looked this good : )', '2004-09-03 00:02:52.000000', NULL, 1),
