(893317, 101289, 12733, '<td valign="top">She looks surprisingly like someone on the pirate ship in Kidnapped! Very nice shot; the lighting and the expectant look on her face really make it.</td>', 'She looks surprisingly like someone on the pirate ship in Kidnapped! Very nice shot; the lighting and the expectant look on her face really make it.', '2004-09-04 23:32:53.000000', NULL, 1),
(893321, 101272, 12733, '<td valign="top">Don''t be fooled, frogs have used that line for years knowing how easily women fall for it. Very nice frog portrait, good use of selective focus to make it stand out.</td>', 'Don''t be fooled, frogs have used that line for years knowing how easily women fall for it. Very nice frog portrait, good use of selective focus to make it stand out.', '2004-09-04 23:34:54.000000', NULL, 1),
(893323, 101030, 12733, '<td valign="top">Great still life; I really like the contrasts and colors.</td>', 'Great still life; I really like the contrasts and colors.', '2004-09-04 23:36:05.000000', NULL, 1),
